---@class UIFeelingFavorabilityFigureRoleNode
local UIFeelingFavorabilityFigureRoleNode = Class("UIFeelingFavorabilityFigureRoleNode")
function UIFeelingFavorabilityFigureRoleNode:__init() 
    self._curCardId = nil
    self._curCatId = nil
    self._clickCb = nil
end

function UIFeelingFavorabilityFigureRoleNode:__delete()
    self._curCardId = nil
    self._curCatId = nil
    self._clickCb = nil
end

function UIFeelingFavorabilityFigureRoleNode:Awake()
    SetButtonAction(self.ImgRoleBg, Bind(self, self.OnSelectCat))
end

function UIFeelingFavorabilityFigureRoleNode:Start()
    CfUtils.FillText(self.Text, localize("当前"))
end

function UIFeelingFavorabilityFigureRoleNode:Refresh(id, catId, clickCb)
    self._curCardId = checkNumber(id)
    self._clickCb = clickCb
    self._curCatId = checkNumber(catId)

    local vo = CardConfMgr:GetInstance():GetCardByRefId(id)
    if vo then
        CfUtils.FillText(self.TxtName, vo.descr)
        CfUtils.FillText(self.TxtName2, vo.name)
        CfUtils.FillImage(self.ImgRoleIcon, CardConfMgr:GetInstance():GetCardDefaultBodyIconPath(id))
        CfUtils.SetUISwitchImage(self.Root.transform:Find("RolePanel/imgBg"), 4 - checkNumber(vo.rare))
    end
    KTool.SetActive(self.Imgselect, self._curCardId == checkNumber(PhoneUtils.GetRoleCurCardSkinId(self._curCatId)))    
    KTool.SetActive(self.Root, true)
end

function UIFeelingFavorabilityFigureRoleNode:FillSelect()
    CfUtils.SetScale(self.Root, Vector3(1.1, 1.1, 1.1))
    KTool.SetActive(self.Root.transform:Find("ImgMask"), true)
    CfUtils.FillImage(self.ImgRoleBg, "UIAtlas/Feeling/Favorability/feeling_feel_role_bg_2.png")
end

function UIFeelingFavorabilityFigureRoleNode:FillUnSelect()
    CfUtils.SetScale(self.Root, Vector3(1, 1, 1))
    KTool.SetActive(self.Root.transform:Find("ImgMask"), false)
    CfUtils.FillImage(self.ImgRoleBg, "UIAtlas/Feeling/Favorability/feeling_feel_role_bg_1.png")
end

function UIFeelingFavorabilityFigureRoleNode:OnSelectCat()
    if self._clickCb then
        self._clickCb()
    end
end

function UIFeelingFavorabilityFigureRoleNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFeelingFavorabilityFigureRoleNode
